from __future__ import annotations

from datetime import datetime, timedelta
from decimal import Decimal
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.adapters.bedrock import EventExtractionError
from catalyst_router.decision import DecisionEngine
from catalyst_router.domain import (
    DecisionRecord,
    Event,
    EventDirection,
    NewsArticle,
    QuoteSnapshot,
    Route,
    SignalFrame,
)
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector


class NewsSource(Protocol):
    def recent_news(
        self,
        symbols: tuple[str, ...],
        *,
        since: datetime,
        until: datetime,
    ) -> tuple[NewsArticle, ...]: ...


class EventExtractor(Protocol):
    model_id: str
    prompt_version: str

    def extract(self, article: NewsArticle) -> Event: ...


class QuoteSource(Protocol):
    def latest_quote(self, symbol: str) -> QuoteSnapshot: ...


class ShadowEventRouter:
    """Records LLM Event evidence and deterministic route decisions without order authority."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        news: NewsSource,
        extractor: EventExtractor,
        quotes: QuoteSource,
        engine: DecisionEngine | None = None,
    ) -> None:
        self._store = store
        self._news = news
        self._extractor = extractor
        self._quotes = quotes
        self._engine = engine or DecisionEngine()
        self._processed_source_ids: set[str] = set()

    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        if not vectors:
            return ()
        observed_at = max(vector.observed_at for vector in vectors)
        by_symbol = {vector.symbol: vector for vector in vectors}
        articles = self._news.recent_news(
            tuple(sorted(by_symbol)),
            since=observed_at - timedelta(minutes=15),
            until=observed_at,
        )
        records: list[DecisionRecord] = []
        for article in articles:
            if article.source_id in self._processed_source_ids:
                continue
            try:
                event = self._extractor.extract(article)
            except EventExtractionError as exc:
                record = self._failure_record(article, observed_at, str(exc))
                if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                    records.append(record)
                self._processed_source_ids.add(article.source_id)
                continue
            for symbol in event.affected_symbols:
                vector = by_symbol.get(symbol)
                if vector is None:
                    continue
                quote = self._quotes.latest_quote(symbol)
                decision = self._engine.evaluate(self._signal_frame(event, vector, quote))
                record = self._route_record(event, decision.route, symbol, observed_at)
                if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                    records.append(record)
            self._processed_source_ids.add(article.source_id)
        return tuple(records)

    def _signal_frame(
        self, event: Event, vector: FeatureVector, quote: QuoteSnapshot
    ) -> SignalFrame:
        features = dict(zip(vector.names, vector.values, strict=True))
        momentum = _clamp(Decimal(str(features["relative_return_1h"])) * Decimal("100"))
        regime = abs(_clamp(Decimal(str(features["market_return_1h"])) * Decimal("100")))
        direction = {
            EventDirection.BULLISH: Decimal("1"),
            EventDirection.BEARISH: Decimal("-1"),
            EventDirection.NEUTRAL: Decimal("0"),
        }[event.direction]
        quote_age = vector.observed_at - quote.timestamp
        data_quality_passed = timedelta(0) <= quote_age <= timedelta(seconds=5)
        return SignalFrame(
            symbol=vector.symbol,
            observed_at=vector.observed_at,
            expected_horizon_minutes=event.expected_horizon_minutes,
            has_credible_event=event.direction is not EventDirection.NEUTRAL,
            event_confidence=event.confidence,
            event_novelty=event.novelty,
            event_direction=direction,
            momentum_score=momentum,
            reversion_score=Decimal("0"),
            regime_score=regime,
            spread_bps=quote.spread_bps,
            expected_edge_bps=event.magnitude * Decimal("100"),
            estimated_cost_bps=Decimal("8"),
            data_quality_passed=data_quality_passed,
            exposure_group=("us-equity:long" if direction >= 0 else "us-equity:short"),
        )

    def _route_record(
        self,
        event: Event,
        route: Route,
        symbol: str,
        observed_at: datetime,
    ) -> DecisionRecord:
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "llm-event-route",
                        event.source_id,
                        event.model_id,
                        event.prompt_version,
                        symbol,
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="LLM_EVENT_ROUTE",
            occurred_at=observed_at,
            route=route,
            symbol=symbol,
            summary=f"shadow LLM Event route {route} for {symbol}",
            payload={
                "authority": "SHADOW_ONLY",
                "event": event.model_dump(mode="json"),
                "route": route,
            },
            public=True,
            public_summary=f"Event evidence route: {route}",
        )

    def _failure_record(
        self, article: NewsArticle, observed_at: datetime, reason: str
    ) -> DecisionRecord:
        return DecisionRecord.create(
            decision_id=str(
                uuid5(
                    NAMESPACE_URL,
                    f"llm-event-failure:{article.source_id}:{self._extractor.prompt_version}",
                )
            ),
            decision_type="LLM_EVENT_ROUTE",
            occurred_at=observed_at,
            route=Route.NO_TRADE,
            summary=f"LLM Event extraction failed closed: {reason}",
            payload={
                "authority": "SHADOW_ONLY",
                "source_id": article.source_id,
                "model_id": self._extractor.model_id,
                "prompt_version": self._extractor.prompt_version,
                "reason": reason,
            },
            public=True,
            public_summary="Event evidence unavailable; no trade",
        )


def _clamp(value: Decimal) -> Decimal:
    return max(Decimal("-1"), min(Decimal("1"), value))

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta
from decimal import ROUND_CEILING, ROUND_FLOOR, Decimal
from typing import Literal, Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import (
    AgentMode,
    BrokerOrderSnapshot,
    DecisionRecord,
    InstrumentType,
    OrderExecution,
    OrderExecutionStatus,
    OrderPlan,
    PortfolioRiskState,
    QuoteSnapshot,
    ReconciliationSnapshot,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.risk import RiskGovernor
from catalyst_router.training import FEATURE_SCHEMA, FeatureVector

_CENT = Decimal("0.01")


@dataclass(frozen=True, slots=True)
class EntrySignal:
    route: Route
    side: Side
    confidence: Decimal
    source: str


class EntryStrategy(Protocol):
    def signal(self, vector: FeatureVector) -> EntrySignal | None: ...

    def create_intent(
        self,
        vector: FeatureVector,
        quote: QuoteSnapshot,
        *,
        signal: EntrySignal | None = None,
        now: datetime | None = None,
    ) -> TradeIntent | None: ...


class IncumbentStrategy:
    """Conservative deterministic policy authorized for the first paper execution slice."""

    MAX_QUOTE_AGE = timedelta(seconds=5)
    MAX_FEATURE_AGE = timedelta(minutes=7)
    MAX_SPREAD_BPS = Decimal("15")

    def create_intent(
        self,
        vector: FeatureVector,
        quote: QuoteSnapshot,
        *,
        signal: EntrySignal | None = None,
        now: datetime | None = None,
    ) -> TradeIntent | None:
        observed_now = now or datetime.now(UTC)
        if vector.schema != FEATURE_SCHEMA or quote.symbol != vector.symbol:
            return None
        feature_age = observed_now - vector.observed_at
        quote_age = observed_now - quote.timestamp
        if not timedelta(0) <= feature_age <= self.MAX_FEATURE_AGE:
            return None
        if not timedelta(0) <= quote_age <= self.MAX_QUOTE_AGE:
            return None
        if quote.spread_bps > self.MAX_SPREAD_BPS:
            return None

        selected = signal or self.signal(vector)
        if selected is None:
            return None

        entry_price = quote.ask_price.quantize(_CENT, rounding=ROUND_CEILING)
        stop_price = (entry_price * Decimal("0.98")).quantize(_CENT, rounding=ROUND_FLOOR)
        intent_id = str(
            uuid5(
                NAMESPACE_URL,
                f"{selected.source}:{selected.route}:{vector.symbol}:{vector.observed_at.isoformat()}",
            )
        )
        return TradeIntent(
            intent_id=intent_id,
            route=selected.route,
            symbol=vector.symbol,
            instrument_type=InstrumentType.EQUITY,
            side=selected.side,
            confidence=selected.confidence,
            entry_price=entry_price,
            stop_price=stop_price,
            expected_horizon_minutes=(60 if selected.route is Route.LIQUIDITY_REVERSION else 240),
            exposure_group="us-equity:long",
            quote_age_seconds=Decimal(str(quote_age.total_seconds())),
            data_quality_passed=True,
        )

    def signal(self, vector: FeatureVector) -> EntrySignal | None:
        route = self.route(vector)
        if route is None:
            return None
        return EntrySignal(
            route=route,
            side=Side.BUY,
            confidence=(Decimal("0.85") if route is Route.REGIME_TREND else Decimal("0.80")),
            source="incumbent-v1",
        )

    @staticmethod
    def route(vector: FeatureVector) -> Route | None:
        if vector.schema != FEATURE_SCHEMA:
            return None
        features = dict(zip(vector.names, vector.values, strict=True))
        if vector.symbol in {"SPY", "QQQ"} and (
            features["return_15m"] > 0
            and features["return_1h"] >= 0.002
            and features["return_3h"] >= 0.005
            and features["close_location_5h"] >= 0.2
        ):
            return Route.REGIME_TREND
        elif vector.symbol not in {"SPY", "QQQ"} and (
            features["return_15m"] >= 0.0005
            and features["relative_return_1h"] <= -0.005
            and features["vwap_distance"] >= 0
            and features["close_location_5h"] <= -0.3
            and features["cross_sectional_return_rank_1h"] <= -0.35
        ):
            return Route.LIQUIDITY_REVERSION
        return None


class ModelPredictor(Protocol):
    status: PublicChallengerStatus
    prediction_kind: Literal["probability", "return"]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class ModelStrategy:
    """Turns sufficiently directional model predictions into paper trade intents."""

    MAX_QUOTE_AGE = timedelta(seconds=5)
    MAX_FEATURE_AGE = timedelta(minutes=7)
    MAX_SPREAD_BPS = Decimal("15")

    def __init__(self, predictor: ModelPredictor, *, decision_gate: Decimal) -> None:
        if predictor.status.authority != "PAPER_LIVE":
            raise ValueError("model must have PAPER_LIVE authority")
        if predictor.prediction_kind != "probability":
            raise ValueError("live model execution requires probability predictions")
        if not Decimal("0.5") < decision_gate <= Decimal("1"):
            raise ValueError("model decision gate must be greater than 0.5 and at most 1")
        self._predictor = predictor
        self._decision_gate = decision_gate

    def signal(self, vector: FeatureVector) -> EntrySignal | None:
        prediction = self._predictor.predict(vector)
        value = Decimal(str(prediction.value))
        if value >= self._decision_gate:
            side = Side.BUY
            confidence = value
        elif value <= Decimal("1") - self._decision_gate:
            side = Side.SELL
            confidence = Decimal("1") - value
        else:
            return None
        return EntrySignal(
            route=Route.MODEL_DIRECTIONAL,
            side=side,
            confidence=confidence,
            source=f"model-paper-v1:{prediction.run_id}:gate-{self._decision_gate}",
        )

    def create_intent(
        self,
        vector: FeatureVector,
        quote: QuoteSnapshot,
        *,
        signal: EntrySignal | None = None,
        now: datetime | None = None,
    ) -> TradeIntent | None:
        observed_now = now or datetime.now(UTC)
        if vector.schema != FEATURE_SCHEMA or quote.symbol != vector.symbol:
            return None
        feature_age = observed_now - vector.observed_at
        quote_age = observed_now - quote.timestamp
        if not timedelta(0) <= feature_age <= self.MAX_FEATURE_AGE:
            return None
        if not timedelta(0) <= quote_age <= self.MAX_QUOTE_AGE:
            return None
        if quote.spread_bps > self.MAX_SPREAD_BPS:
            return None

        selected = signal or self.signal(vector)
        if selected is None:
            return None
        if selected.side is Side.BUY:
            entry_price = quote.ask_price.quantize(_CENT, rounding=ROUND_CEILING)
            stop_price = (entry_price * Decimal("0.98")).quantize(_CENT, rounding=ROUND_FLOOR)
            exposure_group = "us-equity:long"
        else:
            entry_price = quote.bid_price.quantize(_CENT, rounding=ROUND_FLOOR)
            stop_price = (entry_price * Decimal("1.02")).quantize(_CENT, rounding=ROUND_CEILING)
            exposure_group = "us-equity:short"
        intent_id = str(
            uuid5(
                NAMESPACE_URL,
                (
                    f"{selected.source}:{selected.side}:{vector.symbol}:"
                    f"{vector.observed_at.isoformat()}"
                ),
            )
        )
        return TradeIntent(
            intent_id=intent_id,
            route=selected.route,
            symbol=vector.symbol,
            instrument_type=InstrumentType.EQUITY,
            side=selected.side,
            confidence=selected.confidence,
            entry_price=entry_price,
            stop_price=stop_price,
            expected_horizon_minutes=240,
            exposure_group=exposure_group,
            quote_age_seconds=Decimal(str(quote_age.total_seconds())),
            data_quality_passed=True,
        )


class QuoteSource(Protocol):
    def latest_quote(self, symbol: str) -> QuoteSnapshot: ...


class LiveTradingCycle:
    """Evaluates the incumbent and submits at most one protected equity entry."""

    MAX_ENTRY_NOTIONAL_RATE = Decimal("0.10")

    def __init__(
        self,
        *,
        store: OperationalStore,
        broker: PaperBroker,
        quotes: QuoteSource,
        strategy: EntryStrategy | None = None,
        risk_governor: RiskGovernor | None = None,
    ) -> None:
        self._store = store
        self._broker = broker
        self._quotes = quotes
        self._strategy = strategy or IncumbentStrategy()
        self._risk = risk_governor or RiskGovernor()
        self._gateway = ExecutionGateway(store=store, broker=broker)

    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        agent = self._store.get_agent_state()
        if agent.mode is not AgentMode.RUNNING:
            return ()
        if agent.execution_epoch != expected_epoch or not agent.is_reconciled:
            raise RuntimeError("worker lost execution epoch ownership")

        snapshot = self._broker.reconciliation_snapshot()
        agent = self._store.update_equity_peak(snapshot.account.equity)
        active_execution = (
            self._store.get_order(agent.active_order_id)
            if agent.active_order_id is not None
            else None
        )
        until_close = snapshot.clock.next_close - snapshot.clock.timestamp
        if active_execution is not None:
            self._release_terminal_order(
                agent.active_order_id or active_execution.plan.client_order_id,
                snapshot,
                active_execution,
            )
            agent = self._store.get_agent_state()
            active_execution = (
                self._store.get_order(agent.active_order_id)
                if agent.active_order_id is not None
                else None
            )
        horizon_expired = (
            active_execution is not None
            and snapshot.clock.timestamp >= active_execution.plan.expires_at
        )
        close_flatten_due = bool(
            snapshot.positions or snapshot.open_orders
        ) and until_close <= timedelta(minutes=10)
        if horizon_expired or close_flatten_due:
            self._broker.flatten()
            return ()
        last_equity = snapshot.account.last_equity or snapshot.account.equity
        equity_peak = agent.equity_peak or max(last_equity, snapshot.account.equity)
        portfolio = PortfolioRiskState(
            equity=snapshot.account.equity,
            buying_power=min(
                snapshot.account.buying_power,
                snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
            ),
            position_count=0,
            total_open_risk=Decimal("0"),
            overnight_open_risk=Decimal("0"),
            group_open_risk={},
            daily_pnl=snapshot.account.equity - last_equity,
            competition_drawdown=max(
                Decimal("0"),
                (equity_peak - snapshot.account.equity) / equity_peak,
            ),
        )
        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if portfolio.competition_drawdown >= RiskGovernor.MAX_COMPETITION_DRAWDOWN_RATE:
            self._halt_and_flatten(AgentMode.KILLED, "competition drawdown kill threshold reached")
            return ()
        if daily_loss >= portfolio.equity * RiskGovernor.MAX_DAILY_LOSS_RATE:
            self._halt_and_flatten(AgentMode.RISK_HALTED, "daily loss circuit breaker reached")
            return ()
        if snapshot.positions and len(snapshot.open_orders) < 2:
            self._halt_and_flatten(
                AgentMode.RISK_HALTED,
                "broker position is missing protective bracket exits",
            )
            return ()
        if (
            agent.active_order_id is not None
            or not snapshot.clock.is_open
            or snapshot.account.trading_blocked
            or snapshot.positions
            or snapshot.open_orders
            or until_close <= timedelta(minutes=15)
        ):
            return ()
        candidates = [
            (signal, vector)
            for vector in vectors
            if (signal := self._strategy.signal(vector)) is not None
        ]
        for signal, vector in sorted(
            candidates, key=lambda item: (-item[0].confidence, item[1].symbol)
        ):
            quote = self._quotes.latest_quote(vector.symbol)
            intent = self._strategy.create_intent(vector, quote, signal=signal)
            if intent is None:
                continue
            risk = self._risk.evaluate(
                intent,
                agent,
                portfolio,
                market_is_open=snapshot.clock.is_open,
                trading_blocked=snapshot.account.trading_blocked,
            )
            if risk.status is RiskDecisionStatus.VETOED:
                return self._persist_risk_veto(intent, risk, expected_epoch)
            approvals = self._persist_risk_approval(intent, risk, portfolio, expected_epoch)
            execution = self._gateway.execute(intent, risk, expected_epoch=expected_epoch)
            return approvals + self._persist_execution(intent, risk, execution, expected_epoch)
        return ()

    def _release_terminal_order(
        self,
        client_order_id: str,
        snapshot: ReconciliationSnapshot,
        execution: OrderExecution,
    ) -> None:
        broker_order = self._broker.get_order_by_client_id(client_order_id)
        status = (
            broker_order.status.rsplit(".", 1)[-1].lower()
            if broker_order is not None
            else "missing"
        )
        terminal = status in {"canceled", "expired", "filled", "rejected", "replaced"}
        expired_and_missing = (
            status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
        )
        if (
            (terminal or expired_and_missing)
            and not snapshot.positions
            and not snapshot.open_orders
        ):
            self._store.clear_active_order(client_order_id)

    def _halt_and_flatten(self, mode: AgentMode, reason: str) -> None:
        self._store.transition_agent_mode(
            mode,
            reason=reason,
            record=DecisionRecord.create(
                decision_type="CIRCUIT_BREAKER",
                summary=reason,
                payload={"mode": mode, "reason": reason},
            ),
        )
        self._broker.flatten()

    def _persist_risk_veto(
        self, intent: TradeIntent, risk: RiskDecision, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-veto:{intent.intent_id}")),
            decision_type="RISK_VETO",
            route=intent.route,
            symbol=intent.symbol,
            summary="; ".join(risk.checks),
            payload={"intent_id": intent.intent_id, "checks": risk.checks},
            public=True,
            public_summary=f"Risk governor vetoed {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_risk_approval(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        portfolio: PortfolioRiskState,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-approval:{intent.intent_id}")),
            decision_type="RISK_APPROVAL",
            route=intent.route,
            symbol=intent.symbol,
            summary=f"approved {risk.quantity} shares with {risk.risk_amount} stop risk",
            payload={
                "intent_id": intent.intent_id,
                "status": risk.status,
                "quantity": risk.quantity,
                "risk_amount": str(risk.risk_amount),
                "checks": risk.checks,
                "account_snapshot": {
                    "equity": str(portfolio.equity),
                    "buying_power": str(portfolio.buying_power),
                    "position_count": portfolio.position_count,
                    "total_open_risk": str(portfolio.total_open_risk),
                    "daily_pnl": str(portfolio.daily_pnl),
                    "competition_drawdown": str(portfolio.competition_drawdown),
                },
            },
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_execution(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        execution: OrderExecution,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(
                uuid5(NAMESPACE_URL, f"order-execution:{execution.plan.client_order_id}")
            ),
            decision_type="ORDER_EXECUTION",
            route=intent.route,
            symbol=intent.symbol,
            summary=(
                f"{execution.status} paper bracket {execution.plan.client_order_id} "
                f"for {execution.plan.quantity} {intent.symbol}"
            ),
            payload={
                "client_order_id": execution.plan.client_order_id,
                "status": execution.status,
                "quantity": execution.plan.quantity,
                "risk_amount": str(risk.risk_amount),
                "limit_price": str(execution.plan.limit_price),
                "stop_price": str(execution.plan.stop_price),
                "take_profit_price": str(execution.plan.take_profit_price),
            },
            public=True,
            public_summary=f"Paper bracket order {execution.status.lower()} for {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )


class ExecutionGateway:
    def __init__(self, *, store: OperationalStore, broker: PaperBroker) -> None:
        self._store = store
        self._broker = broker

    def execute(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        *,
        expected_epoch: str,
    ) -> OrderExecution:
        if risk.intent_id != intent.intent_id or risk.status is RiskDecisionStatus.VETOED:
            raise ValueError("an approved risk decision matching the intent is required")
        plan = self._plan(intent, risk)
        prepared = OrderExecution(plan=plan, request_hash=self._request_hash(plan))
        claimed = self._store.claim_order(prepared, expected_epoch=expected_epoch)
        execution = prepared if claimed else self._store.get_order(plan.client_order_id)
        if execution is None:
            raise RuntimeError("claimed order execution could not be loaded")
        if execution.request_hash != prepared.request_hash:
            raise RuntimeError("client order id was reused with a different request")
        if execution.status in {
            OrderExecutionStatus.ACKNOWLEDGED,
            OrderExecutionStatus.REJECTED,
        }:
            return execution

        broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
        if broker_order is not None:
            return self._acknowledge(execution, broker_order)
        try:
            broker_order = self._broker.submit_order(plan)
        except Exception:
            broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
            if broker_order is not None:
                return self._acknowledge(execution, broker_order)
            return self._transition(execution, OrderExecutionStatus.UNKNOWN)
        return self._acknowledge(execution, broker_order)

    @staticmethod
    def _plan(intent: TradeIntent, risk: RiskDecision) -> OrderPlan:
        client_order_id = "cr-" + uuid5(NAMESPACE_URL, f"paper-order-v1:{intent.intent_id}").hex
        take_profit = (
            (intent.entry_price * Decimal("1.04")).quantize(_CENT, rounding=ROUND_CEILING)
            if intent.side is Side.BUY
            else (intent.entry_price * Decimal("0.96")).quantize(_CENT, rounding=ROUND_FLOOR)
        )
        created_at = datetime.now(UTC)
        return OrderPlan(
            client_order_id=client_order_id,
            intent_id=intent.intent_id,
            symbol=intent.symbol,
            side=intent.side,
            quantity=risk.quantity,
            limit_price=intent.entry_price,
            stop_price=intent.stop_price,
            take_profit_price=take_profit,
            risk_amount=risk.risk_amount,
            exposure_group=intent.exposure_group,
            created_at=created_at,
            expires_at=created_at + timedelta(minutes=intent.expected_horizon_minutes),
        )

    @staticmethod
    def _request_hash(plan: OrderPlan) -> str:
        request = {
            "client_order_id": plan.client_order_id,
            "limit_price": str(plan.limit_price),
            "quantity": plan.quantity,
            "side": plan.side,
            "stop_price": str(plan.stop_price),
            "symbol": plan.symbol,
            "take_profit_price": str(plan.take_profit_price),
            "time_in_force": "day",
            "type": "limit",
        }
        encoded = json.dumps(request, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def _acknowledge(
        self, execution: OrderExecution, broker_order: BrokerOrderSnapshot
    ) -> OrderExecution:
        plan = execution.plan
        if (
            broker_order.client_order_id != plan.client_order_id
            or broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("Alpaca order does not match the durable order plan")
        status = broker_order.status.rsplit(".", 1)[-1].lower()
        target = (
            OrderExecutionStatus.REJECTED
            if status in {"canceled", "expired", "rejected", "replaced"}
            else OrderExecutionStatus.ACKNOWLEDGED
        )
        updated = self._transition(
            execution,
            target,
            alpaca_order_id=broker_order.order_id,
            broker_status=broker_order.status,
        )
        if target is OrderExecutionStatus.REJECTED:
            self._store.clear_active_order(plan.client_order_id)
        return updated

    def _transition(
        self,
        execution: OrderExecution,
        status: OrderExecutionStatus,
        *,
        alpaca_order_id: str | None = None,
        broker_status: str | None = None,
    ) -> OrderExecution:
        updated = execution.model_copy(
            update={
                "status": status,
                "version": execution.version + 1,
                "alpaca_order_id": alpaca_order_id or execution.alpaca_order_id,
                "broker_status": broker_status or execution.broker_status,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._store.update_order(updated, expected_status=execution.status)

from __future__ import annotations

from datetime import datetime
from typing import Protocol, cast

from alpaca.data.historical.news import NewsClient
from alpaca.data.models.news import News, NewsSet
from alpaca.data.requests import NewsRequest

from catalyst_router.domain import NewsArticle


class _NewsClient(Protocol):
    def get_news(self, request: NewsRequest) -> NewsSet: ...


class AlpacaNewsSource:
    def __init__(
        self,
        key: str,
        secret: str,
        *,
        client: _NewsClient | None = None,
    ) -> None:
        self._client = client or cast(_NewsClient, NewsClient(key, secret))

    def recent_news(
        self,
        symbols: tuple[str, ...],
        *,
        since: datetime,
        until: datetime,
    ) -> tuple[NewsArticle, ...]:
        response = self._client.get_news(
            NewsRequest(
                symbols=",".join(symbols),
                start=since,
                end=until,
                sort="asc",
                limit=50,
                include_content=True,
                exclude_contentless=True,
            )
        )
        requested = set(symbols)
        articles: dict[int, News] = {}
        for items in response.data.values():
            for item in items:
                articles[item.id] = item
        return tuple(
            NewsArticle(
                source_id=f"alpaca:{item.id}",
                headline=item.headline,
                summary=item.summary,
                content=item.content,
                source=item.source,
                author=item.author,
                url=item.url,
                published_at=item.created_at,
                updated_at=item.updated_at,
                symbols=tuple(
                    sorted(symbol for symbol in set(item.symbols) if symbol in requested)
                ),
            )
            for item in sorted(articles.values(), key=lambda value: (value.created_at, value.id))
            if requested.intersection(item.symbols)
        )

from __future__ import annotations

import logging
import time
from collections.abc import Callable
from datetime import UTC, datetime
from pathlib import Path
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import DecisionRecord
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector, MarketBar, build_feature_vectors

logger = logging.getLogger(__name__)


class MarketData(Protocol):
    def recent_bars(
        self,
        symbols: tuple[str, ...],
        *,
        timeframe_minutes: int,
        lookback_days: int,
    ) -> list[MarketBar]: ...


class ChallengerPredictor(Protocol):
    status: PublicChallengerStatus
    symbols: tuple[str, ...]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class FeatureBuilder(Protocol):
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]: ...


class LiveTrader(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class EventRouter(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class LiveFeatureBuilder:
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]:
        return build_feature_vectors(bars)


class TradingWorker:
    """Runs the always-on inference cycle; execution remains separately gated."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        market_data: MarketData,
        challenger: ChallengerPredictor,
        feature_builder: FeatureBuilder | None = None,
        live_trader: LiveTrader | None = None,
        event_router: EventRouter | None = None,
        live_started_at: datetime | None = None,
    ) -> None:
        self._store = store
        self._market_data = market_data
        self._challenger = challenger
        self._feature_builder = feature_builder or LiveFeatureBuilder()
        self._live_trader = live_trader
        self._event_router = event_router
        self._live_started_at = (
            live_started_at or datetime.now(UTC) if live_trader is not None else None
        )
        self._execution_epoch: str | None = None
        self._bars: dict[tuple[str, datetime], MarketBar] = {}
        self._market_data_bootstrapped = False

    def run_cycle(self) -> tuple[DecisionRecord, ...]:
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("worker execution epoch is not reconciled")
        if self._execution_epoch is not None and state.execution_epoch != self._execution_epoch:
            raise RuntimeError("worker lost execution epoch ownership")
        if not self._challenger.status.deployed or not self._challenger.status.loaded:
            raise RuntimeError("challenger is not ready for inference")
        timeframe = self._challenger.status.timeframe_minutes or 5
        bars = self._market_data.recent_bars(
            self._challenger.symbols,
            timeframe_minutes=timeframe,
            lookback_days=10 if not self._market_data_bootstrapped else 1,
        )
        self._market_data_bootstrapped = True
        self._bars.update({(bar.symbol, bar.timestamp): bar for bar in bars})
        vectors = self._feature_builder.build(list(self._bars.values()))
        if not vectors:
            return ()
        latest_by_symbol: dict[str, datetime] = {}
        for vector in vectors:
            latest_by_symbol[vector.symbol] = max(
                vector.observed_at,
                latest_by_symbol.get(vector.symbol, vector.observed_at),
            )
        latest_vectors = tuple(
            vector for vector in vectors if vector.observed_at == latest_by_symbol[vector.symbol]
        )
        expected_epoch = self._execution_epoch or state.execution_epoch
        records = []
        for vector in latest_vectors:
            prediction = self._challenger.predict(vector)
            record = self._prediction_record(prediction)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                records.append(record)
        if self._event_router is not None:
            records.extend(self._event_router.run(latest_vectors, expected_epoch=expected_epoch))
        if self._live_trader is not None:
            live_vectors = tuple(
                vector
                for vector in latest_vectors
                if self._live_started_at is None or vector.observed_at > self._live_started_at
            )
            if not live_vectors:
                return tuple(records)
            records.extend(self._live_trader.run(live_vectors, expected_epoch=expected_epoch))
        return tuple(records)

    def run_forever(
        self,
        *,
        reconcile: Callable[[], object],
        poll_seconds: int = 15,
        sleep: Callable[[float], None] = time.sleep,
        heartbeat_path: Path = Path("/tmp/worker-heartbeat"),
    ) -> None:
        reconcile()
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("startup reconciliation did not complete")
        self._execution_epoch = state.execution_epoch
        consecutive_failures = 0
        while True:
            try:
                records = self.run_cycle()
                consecutive_failures = 0
                if records:
                    logger.info("persisted %d worker decisions", len(records))
                heartbeat_path.touch()
            except Exception:
                consecutive_failures += 1
                logger.exception("trading worker cycle failed")
                if consecutive_failures >= 5:
                    raise
            sleep(poll_seconds)

    def _prediction_record(self, prediction: ShadowPrediction) -> DecisionRecord:
        authority = self._challenger.status.authority or "SHADOW_ONLY"
        model_label = "paper-live model" if authority == "PAPER_LIVE" else "shadow model"
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "challenger-prediction",
                        prediction.run_id,
                        prediction.symbol,
                        prediction.observed_at.isoformat(),
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="CHALLENGER_PREDICTION",
            occurred_at=prediction.observed_at,
            symbol=prediction.symbol,
            summary=(
                f"{model_label} {prediction.run_id} predicted {prediction.value:.6f} "
                f"({prediction.signal})"
            ),
            payload={
                "authority": authority,
                "run_id": prediction.run_id,
                "value": prediction.value,
                "signal": prediction.signal,
            },
            public=True,
            public_summary=f"{model_label.title()} signal: {prediction.signal}",
        )

from __future__ import annotations

from dataclasses import dataclass

from catalyst_router.adapters.alpaca import AlpacaPaperBroker
from catalyst_router.adapters.bedrock import BedrockEventExtractor
from catalyst_router.adapters.dynamodb import DynamoOperationalStore
from catalyst_router.adapters.market_data import AlpacaIEXMarketData
from catalyst_router.adapters.memory import InMemoryOperationalStore
from catalyst_router.adapters.news import AlpacaNewsSource
from catalyst_router.challenger import ShadowChallenger
from catalyst_router.events import ShadowEventRouter
from catalyst_router.execution import LiveTradingCycle, ModelStrategy
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.service import ReconciliationService
from catalyst_router.settings import Settings
from catalyst_router.worker import TradingWorker


@dataclass(slots=True)
class Container:
    settings: Settings
    store: OperationalStore
    broker: PaperBroker | None
    challenger: ShadowChallenger | None = None
    market_data: AlpacaIEXMarketData | None = None

    @classmethod
    def build(cls, settings: Settings) -> Container:
        if settings.state_backend == "memory":
            store: OperationalStore = InMemoryOperationalStore(settings.public_delay_seconds)
        elif settings.state_backend == "dynamodb":
            store = DynamoOperationalStore(
                table_name=settings.dynamodb_table,
                competition_id=settings.competition_id,
                region=settings.aws_region,
                endpoint_url=settings.dynamodb_endpoint_url,
                public_delay_seconds=settings.public_delay_seconds,
                initialize_missing=settings.runtime_role != "reporting",
            )
        else:
            raise ValueError(f"unsupported STATE_BACKEND: {settings.state_backend}")
        if settings.runtime_role != "reporting":
            store.initialize()

        broker: PaperBroker | None = None
        market_data = None
        if settings.runtime_role != "reporting" and settings.alpaca_key and settings.alpaca_secret:
            broker = AlpacaPaperBroker(settings.alpaca_key, settings.alpaca_secret)
            market_data = AlpacaIEXMarketData(settings.alpaca_key, settings.alpaca_secret)
        if settings.auto_reconcile and broker is None:
            raise RuntimeError("AUTO_RECONCILE requires Alpaca credentials")
        challenger = None
        if settings.challenger_manifest_uri:
            if not settings.challenger_manifest_sha256:
                raise RuntimeError(
                    "CHALLENGER_MANIFEST_SHA256 is required with CHALLENGER_MANIFEST_URI"
                )
            challenger = ShadowChallenger.load_from_s3(
                settings.challenger_manifest_uri,
                settings.aws_region,
                settings.challenger_manifest_sha256,
            )
            if settings.model_authority == "PAPER_LIVE":
                challenger.authorize_paper_execution(settings.model_decision_gate)
        return cls(
            settings=settings,
            store=store,
            broker=broker,
            challenger=challenger,
            market_data=market_data,
        )

    def reconciliation_service(self) -> ReconciliationService:
        if self.broker is None:
            raise RuntimeError("Alpaca credentials are not configured")
        return ReconciliationService(broker=self.broker, store=self.store)

    def trading_worker(self) -> TradingWorker:
        if self.market_data is None:
            raise RuntimeError("Alpaca market data credentials are not configured")
        if self.challenger is None:
            raise RuntimeError("a challenger model is not configured")
        live_trader = None
        event_router = None
        if self.settings.llm_events_enabled:
            if not self.settings.bedrock_model_id:
                raise RuntimeError("Bedrock model is not configured")
            key, secret = self.settings.require_alpaca()
            event_router = ShadowEventRouter(
                store=self.store,
                news=AlpacaNewsSource(key, secret),
                extractor=BedrockEventExtractor(
                    model_id=self.settings.bedrock_model_id,
                    prompt_version=self.settings.bedrock_prompt_version,
                    region=self.settings.aws_region,
                ),
                quotes=self.market_data,
            )
        if self.settings.paper_execution_enabled:
            if self.broker is None:
                raise RuntimeError("paper execution requires Alpaca trading credentials")
            live_trader = LiveTradingCycle(
                store=self.store,
                broker=self.broker,
                quotes=self.market_data,
                strategy=(
                    ModelStrategy(
                        self.challenger,
                        decision_gate=self.settings.model_decision_gate,
                    )
                    if self.settings.model_execution_enabled
                    else None
                ),
            )
        return TradingWorker(
            store=self.store,
            market_data=self.market_data,
            challenger=self.challenger,
            live_trader=live_trader,
            event_router=event_router,
        )

